month_nums={'January':'01','February':'02','March':'03','April':'04','May':'05','June':'06','July':'07','August':'08','September':'09','October':'10','November':'11','December':'12'}

def normalize(url):
    p=urlparse(url)
    q=[(k,v) for k,v in parse_qsl(p.query, keep_blank_values=True) if not (k.startswith('utm_') or k in {'ref','fbclid','gclid','mc_cid','mc_eid'})]
    return urlunparse((p.scheme,p.netloc,p.path,p.params,urlencode(q),''))

def extract_meta(path):
    txt=Path(path).read_text()
    title=txt.splitlines()[0].lstrip('# ').strip()
    m=re.search(r'## Elevator pitch\n(.+)', txt)
    return title, (m.group(1).strip() if m else '')

def bump_version(msg):
    vf=Path('.prompt-hub/version.md')
    parts=vf.read_text().strip().split('.')
    parts[-1]=str(int(parts[-1])+1)
    ver='.'.join(parts)
    vf.write_text(ver+'\n')
    rel=Path('.prompt-hub/releases.md')
    rel.write_text(f'## {ver} - 2026-04-06\n- {msg}\n\n'+rel.read_text())
    return ver

def update_readme(new_link=None):
    p=Path('README.md')
    text=p.read_text()
    if new_link and new_link not in text:
        marker='#### April ('
        idx=text.index(marker)
        line_end=text.index('\n', idx)
        text=text[:line_end+1]+new_link+'\n'+text[line_end+1:]
    lines=text.splitlines()
    counts={}
    current_year=None; current_month=None
    for l in lines:
        m=re.match(r'### (\d{4})', l)
        if m: current_year=m.group(1)
        m2=re.match(r'#### ([A-Za-z]+) \((\d+) article[s]?\)', l)
        if m2: current_month=m2.group(1)
        elif l.startswith('#### '): current_month=None
        elif current_year and current_month and l.startswith('- ['):
            counts[f'{current_year}-{month_nums[current_month]}']=counts.get(f'{current_year}-{month_nums[current_month]}',0)+1
    out=[]; current_year=None
    for l in lines:
        m=re.match(r'### (\d{4})', l)
        if m: current_year=m.group(1)
        m2=re.match(r'#### ([A-Za-z]+) \((\d+) article[s]?\)', l)
        if m2 and current_year:
            name=m2.group(1); c=counts.get(f'{current_year}-{month_nums[name]}',0)
            l=f'#### {name} ({c} article{"s" if c!=1 else ""})'
        out.append(l)
    stat=['## Statistics','','Articles per month:','']
    items=sorted(counts.items())
    for i,(k,c) in enumerate(items):
        stat.append(f"{k} | {'█'*((c+2)//3)} {c}{'<br>' if i < len(items)-1 else ''}")
    text='\n'.join(out)
    text=re.sub(r'## Statistics\n.*?\n## Articles\n','\n'.join(stat)+'\n\n## Articles\n',text,flags=re.S)
    p.write_text(text)

def remove_url(original):
    urls=[u.strip() for u in Path('LIST.md').read_text().splitlines() if u.strip()]
    urls=[u for u in urls if u!=original]
    Path('LIST.md').write_text(('\n'.join(urls)+'\n') if urls else '')

order=[u.strip() for u in Path('LIST.md').read_text().splitlines() if u.strip()]
processed=[]; errors=[]
for original in order:
    clean=normalize(original)
    if clean in articles:
        a=articles[clean]
        path=Path(a['path']); path.parent.mkdir(parents=True, exist_ok=True)
        if not path.exists():
            lines=[f'# {a["title"]}','',f'**Source**: {clean}',f'**Date**: {a["date"]}',f'**Author**: {a["author"]}',f'**Keywords**: {a["keywords"]}','','## Elevator pitch',a['elevator'],'','## Takeaways']
            lines += [f'- {x}' for x in a['takeaways']]
            lines += ['','## Synthesis',a['synth'],'']
            path.write_text('\n'.join(lines))
        update_readme(f"- [{a['title']}]({a['path']})")
        title,elevator,path_str=a['title'],a['elevator'],a['path']
        add=[a['path'],'README.md']
    elif clean in duplicates:
        title,elevator=extract_meta(duplicates[clean]); path_str=duplicates[clean]; add=[]
    else:
        errors.append(f'FETCH_ERROR: {clean} — missing article template')
        remove_url(original)
        bump_version(f'Process article error: {clean}.')
        subprocess.run(['git','add','LIST.md','.prompt-hub/version.md','.prompt-hub/releases.md'], check=True)
        subprocess.run(['git','commit','-m',f'Process article: {clean}'], check=True)
        continue
    remove_url(original)
    bump_version(f'Process article: {title}.')
    mem=Path('.prompt-hub/memory.md')
    mem.write_text(mem.read_text()+f"\n## 2026-04-06 16:00:00 +0200\n- actor: agent\n- action: Processed scan-list URL `{clean}` and updated queue state.\n- files_changed_or_commands: `{', '.join(add+['LIST.md','.prompt-hub/version.md','.prompt-hub/releases.md'])}`.\n- outcome: success\n- next_step: Continue with next URL in LIST.md.\n")
    subprocess.run(['git','add','LIST.md','README.md','.prompt-hub/version.md','.prompt-hub/releases.md','.prompt-hub/memory.md']+([path_str] if add else []), check=True)
    subprocess.run(['git','commit','-m',f'Process article: {title}'], check=True)
    processed.append({'title':title,'elevator':elevator,'path':path_str})
recap=Path('synthesis/2026-04-06 - 160000 - batch recap.md')
recap.parent.mkdir(parents=True, exist_ok=True)
parts=['# Batch Recap - 2026-04-06 16:00:00','']
for p in processed:
    parts += [p['title'],p['elevator'],f'Synthese: {base}{p["path"]}','']
if errors:
    parts += ['## Errors','']+[f'- {e}' for e in errors]
recap.write_text('\n'.join(parts).rstrip()+'\n')
assert all(p['title'] in recap.read_text() for p in processed)
assert Path('LIST.md').read_text()==''
bump_version('Add batch recap: 2026-04-06 160000; finalize scan-list run.')
mem=Path('.prompt-hub/memory.md')
mem.write_text(mem.read_text()+"\n## 2026-04-06 16:00:00 +0200\n- actor: agent\n- action: Created batch recap for scan-list run and verified LIST.md is empty.\n- files_changed_or_commands: `synthesis/2026-04-06 - 160000 - batch recap.md`, `.prompt-hub/version.md`, `.prompt-hub/releases.md`.\n- outcome: success\n- next_step: Push all commits.\n")
subprocess.run(['git','add','synthesis/2026-04-06 - 160000 - batch recap.md','.prompt-hub/version.md','.prompt-hub/releases.md','.prompt-hub/memory.md'], check=True)
subprocess.run(['git','commit','-m','Add batch recap: 2026-04-06 160000'], check=True)
print(json.dumps({'processed':len(processed),'errors':errors}, ensure_ascii=False))
